function countdown(el,seconds,onDone){if(typeof el==='string')el=document.getElementById(el);if(!el)return;clearInterval(timers[el.id]);let t=seconds;const draw=()=>{el.textContent=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`};draw();timers[el.id]=setInterval(()=>{t--;draw();if(t<=0){clearInterval(timers[el.id]);onDone?.();}},1000);}
function currentAccent(){return $('#voiceAccent')?.value||localStorage.getItem(BASE+'Accent')||'en-GB'}
if($('#voiceAccent')){const saved=localStorage.getItem(BASE+'Accent')||'en-GB';$('#voiceAccent').value=saved;$('#voiceAccent').addEventListener('change',e=>localStorage.setItem(BASE+'Accent',e.target.value));}
function speakText(text,button){if(!('speechSynthesis' in window)){alert('Audio playback is not supported in this browser.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=currentAccent();u.rate=.94;u.pitch=1;const old=button?.textContent;u.onstart=()=>{if(button){button.disabled=true;button.textContent='PLAYING…'}};u.onend=()=>{if(button){button.disabled=false;button.textContent=old||'▶ AUDIO'}};u.onerror=u.onend;speechSynthesis.speak(u);}
