let recorder=null,chunks=[],activeKey=null,recorderTimeout=null,recorderInterval=null;
const completedRecordings=new Set(readJSON(`${BASE}_${page}_Recordings`,[]));
async function startRecording(key,seconds,btn){if(!navigator.mediaDevices?.getUserMedia){alert('Microphone recording is not supported in this browser.');return;}if(recorder?.state==='recording')return;try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});chunks=[];activeKey=key;recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'}),audio=document.getElementById(key+'Playback');if(audio){audio.src=URL.createObjectURL(blob);audio.classList.remove('hidden')}stream.getTracks().forEach(t=>t.stop());completedRecordings.add(key);localStorage.setItem(`${BASE}_${page}_Recordings`,JSON.stringify([...completedRecordings]));updateRecordedCounts();renderCFL();};recorder.start();btn.classList.add('recording');btn.textContent='● RECORDING…';const stop=$(`[data-stop="${key}"]`);if(stop)stop.disabled=false;let remaining=seconds;const timer=document.getElementById(key+'Timer');const draw=()=>{if(timer)timer.textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`};draw();clearInterval(recorderInterval);recorderInterval=setInterval(()=>{remaining--;draw();if(remaining<=0)stopRecording(key)},1000);clearTimeout(recorderTimeout);recorderTimeout=setTimeout(()=>stopRecording(key),seconds*1000+200);}catch(e){alert('Microphone permission was not granted. You can still practise aloud.')}}
function stopRecording(key){if(recorder?.state==='recording'&&activeKey===key){recorder.stop();clearTimeout(recorderTimeout);clearInterval(recorderInterval);const btn=$(`[data-record="${key}"]`),stop=$(`[data-stop="${key}"]`);if(btn){btn.classList.remove('recording');btn.textContent=key.toLowerCase().includes('read')?'● RECORD READ-ALOUD':'● RECORD 60s'}if(stop)stop.disabled=true;}}
$$('[data-record]').forEach(b=>b.addEventListener('click',()=>startRecording(b.dataset.record,Number(b.dataset.seconds||60),b)));
