function makeRejoinderCards(target,data,keyBase,{guided=false,final=false}={}){const box=$(target);if(!box)return;const answers=readJSON(keyBase,{});box.innerHTML='';data.forEach((item,i)=>{const f=guided?item.f:'ITEM '+(i+1),s=guided?item.s:item[0],opts=guided?item.o:item[1],a=guided?item.a:item[2];const d=document.createElement('article');d.className='rejoinder-card';d.innerHTML=`<div class="rejoinder-head"><strong>${f}</strong><span class="level-pill">${guided?'GUIDED':'EXAM PRACTICE'}</span></div><div class="rejoinder-body"><div class="statement-console"><div class="statement-copy">${guided?s:'Listen, then choose the best response.'}</div><div class="audio-row"><button class="play-btn" type="button">▶ PLAY PROMPT</button></div></div><div class="option-list"></div>${guided?`<div class="support-row coach-support"><button class="hint-btn" data-localhint="${i}">HINT</button></div><div class="hint hidden" id="localHint_${target.replace('#','')}_${i}">${item.h}</div>`:''}<div class="why-box hidden" id="why_${target.replace('#','')}_${i}"></div></div>`;const play=$('.play-btn',d);play.addEventListener('click',()=>speakText(s,play));opts.forEach((o,oi)=>{const b=document.createElement('button');b.className='choice-btn';b.textContent=`${String.fromCharCode(65+oi)} · ${o}`;if(Number(answers[i])===oi)b.classList.add('selected');b.addEventListener('click',()=>{answers[i]=oi;localStorage.setItem(keyBase,JSON.stringify(answers));$$('.choice-btn',d).forEach((x,j)=>{x.classList.toggle('selected',j===oi);x.classList.remove('correct-choice','wrong-choice')});if(guided||(!final&&mode==='coach')){b.classList.add(oi===a?'correct-choice':'wrong-choice');if(oi!==a)$$('.choice-btn',d)[a].classList.add('correct-choice');const w=$(`#why_${target.replace('#','')}_${i}`);w.classList.remove('hidden');w.innerHTML=`<strong>${oi===a?'Correct ✓':'Not quite.'}</strong> ${guided?item.why:'The best response continues the workplace exchange naturally and directly.'}`;}updateRejoinderCenters();renderCFL();});$('.option-list',d).appendChild(b)});if(guided)$('[data-localhint]',d).addEventListener('click',()=>$('#localHint_'+target.replace('#','')+'_'+i).classList.toggle('hidden'));box.appendChild(d)});return answers;}
function objectiveStats(data,answers){let c=0,a=0;data.forEach((it,i)=>{if(answers[i]!==undefined){a++;const key=it.a!==undefined?it.a:it[2];if(Number(answers[i])===key)c++;}});return{c,a,total:data.length,p:Math.round(c/data.length*100)}}
