function rubricValues(name){return readJSON(`${BASE}_${name}Rubric`,{});}
function rubricStatsFromDom(name){const root=$(`[data-rubric="${name}"]`);if(!root)return{sum:0,p:0,complete:false,selected:0};const sels=$$('select[data-criterion]',root),chosen=sels.filter(s=>s.value!=='');const sum=chosen.reduce((t,s)=>t+Number(s.value),0);return{sum,p:Math.round(sum/25*100),complete:chosen.length===sels.length,selected:chosen.length};}
function initRubric(name,displayId,bigScore,bigPercent){const root=$(`[data-rubric="${name}"]`);if(!root)return null;const key=`${BASE}_${name}Rubric`,values=readJSON(key,{}),selects=$$('select[data-criterion]',root);selects.forEach(s=>{if(values[s.dataset.criterion]!==undefined)s.value=String(values[s.dataset.criterion]);s.addEventListener('change',()=>{if(s.value==='')delete values[s.dataset.criterion];else values[s.dataset.criterion]=Number(s.value);localStorage.setItem(key,JSON.stringify(values));draw();renderCFL();})});function draw(){const st=rubricStatsFromDom(name),submitted=localStorage.getItem(`${BASE}_${name}Submitted`)==='1';if($('#'+displayId))$('#'+displayId).textContent=st.selected?`DRAFT ${st.sum}/25 · ${st.p}%`:'— /25 · choose criteria';if(bigScore&&$('#'+bigScore))$('#'+bigScore).textContent=submitted?`${st.sum}/25`:'—';if(bigPercent&&$('#'+bigPercent))$('#'+bigPercent).textContent=submitted?`${st.p}% TRAINER SCORE`:'NOT SUBMITTED';return st;}draw();return draw;}
