 function renderRead(st){$('#mockLabel').textContent='PART 2 · READ ALOUD';$('#mockTimer').textContent='READ';st.innerHTML=`<div class="official-speaking-screen"><div class="os-instruction">Read the text aloud. Record yourself, then click NEXT.</div><div class="read-text" id="mockReadText">${mockRead}</div><div class="recorder-box"><button class="primary record-btn" data-record="mockRead" data-seconds="90">● RECORD READ-ALOUD</button><button class="secondary" data-stop="mockRead" disabled>■ STOP</button><span class="record-timer" id="mockReadTimer">01:30</span><audio class="playback hidden" id="mockReadPlayback" controls></audio></div></div>`;const b=$('[data-record]',st),stop=$('[data-stop]',st);b.addEventListener('click',()=>startRecording('mockRead',90,b));stop.addEventListener('click',()=>stopRecording('mockRead'));$('#mockNext').disabled=false;$('#mockNext').textContent='NEXT · QUESTION 1';}
 function renderSpoken(st,key,label,q,seconds,bul=[]){$('#mockLabel').textContent=label;$('#mockTimer').textContent='60 SEC';st.innerHTML=`<div class="official-speaking-screen"><div class="os-top"><strong>${label}</strong><strong>Preparation Time</strong></div><div class="os-progress"><span style="width:55%"></span></div><div class="os-instruction">Speak now. Press START RECORDING to begin.</div><div class="prompt-box"><h3>${q}</h3>${bul.length?`<ul>${bul.map(x=>`<li>${x}</li>`).join('')}</ul>`:''}<p>Give as much relevant information as you can.</p></div><div class="recorder-box"><button class="primary record-btn" data-record="${key}" data-seconds="${seconds}">● RECORD 60s</button><button class="secondary" data-stop="${key}" disabled>■ STOP</button><span class="record-timer" id="${key}Timer">01:00</span><audio class="playback hidden" id="${key}Playback" controls></audio></div></div>`;const b=$('[data-record]',st),stop=$('[data-stop]',st);b.addEventListener('click',()=>startRecording(key,seconds,b));stop.addEventListener('click',()=>stopRecording(key));$('#mockNext').disabled=false;$('#mockNext').textContent=state.stage==='topic4'?'FINISH RECORDING ROUTE':'NEXT';}
