function speakSequence(parts,button){if(!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const old=button?.textContent;if(button){button.disabled=true;button.textContent='PLAYING…'};let idx=0;const next=()=>{if(idx>=parts.length){if(button){button.disabled=false;button.textContent=old}return;}const p=parts[idx++],u=new SpeechSynthesisUtterance(p.text);u.lang=currentAccent();u.rate=p.rate||.9;u.pitch=p.pitch||1;u.onend=()=>setTimeout(next,p.pause||0);u.onerror=u.onend;speechSynthesis.speak(u)};next();}
