if($('#downloadCFL'))$('#downloadCFL').addEventListener('click',()=>download(`vtest_lesson_5_${page}_CFL_row.tsv`,$('#cflFicheOutput').textContent,'text/tab-separated-values'));
if($('#downloadCFLDetail'))$('#downloadCFLDetail').addEventListener('click',()=>download(`vtest_lesson_5_${page}_CFL_detail.tsv`,$('#cflOutput').textContent,'text/tab-separated-values'));
if($('#refreshCFL'))$('#refreshCFL').addEventListener('click',()=>{if($('#cflContent')){$('#cflContent').dataset.userEdited='';localStorage.removeItem(`${BASE}_${page}_cflContent`);$('#cflContent').value=autoCFLContent();}renderCFL()});
